-- Miki: Aktivitäten einspielen, Teil 4 von 5 (21 Aktivitäten)
-- ERZEUGT von `npm run db:seed-sql` aus den Dateien in data/. Nicht von Hand ändern.
-- Einfügen im SQL-Editor von Supabase (Anleitung: docs/supabase.md). Zuerst supabase/migrations/0001_activities.sql ausführen,
-- danach alle 5 Teile (die Reihenfolge ist egal). Jeden Teil gefahrlos wiederholbar: Vorhandene Aktivitäten werden aktualisiert,
-- aber nur, wenn sich etwas geändert hat (sonst bliebe updated_at nicht stehen, und jedes Handy lüde sie neu).

insert into public.activities (id, status, category, topics, translations, age_min, age_max, duration_min, duration_max, setting, needs_dry, better_in_sun, day_parts, months, energy, cost, materials, sibling_friendly, source, image, created_at)
values
  ('hopscotch', 'approved', 'movement', array['movement', 'games']::text[], '{"de":{"title":"Hüpfekästchen","summary":"Mit Kreide aufs Pflaster gemalt, einen Stein geworfen und los: das Hüpfspiel, das schon eure Großeltern kannten.","steps":["Malt mit Kreide acht Kästchen auf den Boden: 1, 2 und 3 untereinander, dann 4 und 5 nebeneinander, 6 allein, 7 und 8 nebeneinander. Oben kommt ein Halbkreis als Himmel dazu.","Werft einen flachen Stein in Kästchen 1.","Hüpft über das Kästchen mit dem Stein hinweg durch alle anderen: in einzelnen Kästchen auf einem Bein, in doppelten mit beiden Beinen.","Im Himmel dreht ihr um und hüpft zurück. Auf dem Rückweg hebt ihr den Stein auf, ohne umzufallen.","Geschafft? Dann ist Kästchen 2 dran. Wer auf eine Linie tritt oder daneben wirft, gibt den Stein weiter.","Für Kleine: einfach mit beiden Beinen durchhüpfen, ganz ohne Stein."],"safetyNote":"Malt das Spielfeld nur dort, wo kein Verkehr ist."},"en":{"title":"Hopscotch","summary":"Chalk it on the pavement, toss a stone and off you go: the hopping game your grandparents already knew.","steps":["Draw eight boxes with chalk: 1, 2 and 3 in a column, then 4 and 5 side by side, 6 alone, 7 and 8 side by side. Add a half circle at the top as home.","Toss a flat stone into box 1.","Hop over the box with the stone and through all the others: one foot in single boxes, both feet in double boxes.","At home, turn around and hop back. On the way back, pick up the stone without falling over.","Made it? Then it’s box 2’s turn. Step on a line or miss the box, and the stone passes to the next player.","For little ones: just hop through with both feet, no stone."],"safetyNote":"Only draw the court where there is no traffic."}}'::jsonb, 4, 10, 20, 40, 'outdoor', true, false, null, null, 'medium', 0, array['chalk', 'flatStones']::text[], true, 'ai', null, '2026-10-10T12:00:00.000Z'::timestamptz),
  ('red-light-green-light', 'approved', 'movement', array['movement', 'games']::text[], '{"de":{"title":"Ochs am Berg","summary":"Wer sich bewegt, wenn sich der Ochs umdreht, muss zurück an den Start. Die Eltern dürfen als Ochs stehen bleiben.","steps":["Eine Person ist der Ochs und stellt sich mit dem Rücken zu den anderen an eine Wand oder einen Baum.","Die anderen stellen sich in einiger Entfernung an einer Startlinie auf.","Der Ochs ruft: „Eins, zwei, drei, Ochs am Berg!“ Währenddessen schleichen alle näher heran.","Nach dem Ruf dreht sich der Ochs schnell um, und alle müssen erstarren.","Wer sich noch bewegt, geht zurück an den Start. Wer den Ochs zuerst berührt, ist der nächste Ochs.","Für Kleine ruft der Ochs langsam, für Große schnell und unberechenbar."]},"en":{"title":"Red Light, Green Light","summary":"Whoever moves when the caller turns around goes back to the start. Parents can be the caller and stay put.","steps":["One person is the caller and stands with their back to the others, facing a wall or a tree.","The others line up at a starting line some distance away.","The caller says “Green light!”, and everyone creeps closer.","Then the caller shouts “Red light!” and turns around quickly, and everyone has to freeze.","Anyone still moving goes back to the start. The first one to touch the caller becomes the next caller.","For little ones the caller is slow, for big kids fast and unpredictable."]}}'::jsonb, 3, 14, 15, 30, 'both', false, false, null, null, 'low', 0, array[]::text[], true, 'ai', null, '2026-10-10T12:00:00.000Z'::timestamptz),
  ('family-bike-tour', 'approved', 'movement', array['movement', 'outings']::text[], '{"de":{"title":"Familien-Radtour","summary":"Eine kleine Radtour mit einem Ziel für die Pause: zum See, zur Eisdiele oder zum nächsten Aussichtspunkt.","steps":["Sucht ein Ziel, das alle schaffen: Für Jüngere reichen 5 bis 10 Kilometer hin und zurück, am besten auf Radwegen.","Prüft vor dem Start Reifen, Bremsen und Licht, und alle setzen ihren Helm auf.","Packt Trinkflaschen in den Rucksack.","Fahrt hintereinander. Mit zwei Erwachsenen fährt einer vorn und einer hinten, die Kinder in der Mitte.","Macht am Ziel eine richtige Pause, bevor es zurückgeht.","Größere Kinder planen die Strecke selbst mit einer Karte und führen die Gruppe an."],"safetyNote":"Alle tragen einen Helm. Kinder unter 8 Jahren fahren in Deutschland auf dem Gehweg, eine erwachsene Begleitperson darf dort mitfahren. Plant die Strecke so, dass niemand überfordert ist."},"en":{"title":"Family Bike Tour","summary":"A short bike tour with a destination for your break: a lake, an ice cream shop or the nearest viewpoint.","steps":["Pick a destination everyone can manage: for younger kids, 5 to 10 kilometers there and back is plenty, ideally on bike paths.","Before you set off, check tires, brakes and lights, and everyone puts on their helmet.","Pack water bottles in the backpack.","Ride in a line. With two adults, one rides in front and one at the back, with the children in the middle.","Take a proper break at your destination before you head back.","Older kids plan the route themselves with a map and lead the group."],"safetyNote":"Everyone wears a helmet. In Germany, children under 8 ride on the sidewalk, and one accompanying adult may ride there with them. Plan the route so nobody gets overwhelmed."}}'::jsonb, 6, 16, 60, 180, 'outdoor', true, true, null, null, 'high', 0, array['bike', 'drinkBottle', 'backpack']::text[], true, 'ai', null, '2026-10-10T12:00:00.000Z'::timestamptz),
  ('giant-soap-bubbles', 'approved', 'experiment', array['experiments', 'water']::text[], '{"de":{"title":"Riesen-Seifenblasen","summary":"Mit zwei Strohhalmen und einem Wollfaden zaubert ihr Seifenblasen, die größer sind als euer Kopf.","steps":["Rührt auf einem Backblech oder Tablett 400 Milliliter Wasser, 4 Esslöffel Spülmittel und 2 Teelöffel Zucker vorsichtig zusammen. Es soll nicht schäumen.","Lasst die Lauge ein paar Minuten stehen, dann halten die Blasen besser.","Fädelt einen etwa einen Meter langen Wollfaden durch zwei Strohhalme und knotet die Enden zusammen.","Haltet die Strohhalme wie Griffe, taucht den Faden ganz in die Lauge und hebt ihn langsam heraus.","Zieht die Strohhalme auseinander, sodass eine Seifenhaut entsteht. Geht langsam rückwärts oder lasst den Wind hineinblasen.","Kleine Kinder jagen die Blasen und versuchen, sie zu fangen."],"safetyNote":"Seifenlauge brennt in den Augen: Pustet niemandem ins Gesicht und wascht danach die Hände. Die Lauge ist nicht zum Trinken."},"en":{"title":"Giant Soap Bubbles","summary":"With two straws and a piece of yarn, make soap bubbles bigger than your head.","steps":["On a baking sheet or tray, gently stir together 400 milliliters of water, 4 tablespoons of dish soap and 2 teaspoons of sugar. It shouldn’t foam.","Let the mixture rest for a few minutes, then the bubbles will hold better.","Thread a piece of yarn about one meter long through two straws and tie the ends together.","Hold the straws like handles, dip the yarn completely into the mixture and lift it out slowly.","Pull the straws apart so a film of soap forms. Walk backward slowly or let the wind blow into it.","Little ones chase the bubbles and try to catch them."],"safetyNote":"Soapy water stings in the eyes: don’t blow into anyone’s face, and wash your hands afterwards. The mixture is not for drinking."}}'::jsonb, 3, 10, 20, 40, 'outdoor', true, true, null, null, 'low', 0, array['dishSoap', 'sugar', 'tapWater', 'tray', 'straws', 'wool']::text[], true, 'ai', null, '2026-10-10T12:00:00.000Z'::timestamptz),
  ('cloud-pictures', 'approved', 'nature', array['natureAnimals', 'stories']::text[], '{"de":{"title":"Wolkenbilder entdecken","summary":"Auf einer Decke liegen, in den Himmel schauen und in den Wolken Drachen, Schafe und Gesichter finden.","steps":["Breitet eine Decke im Garten, im Park oder auf einer Wiese aus und legt euch auf den Rücken.","Schaut in die Wolken: Was seht ihr? Ein Krokodil, ein Eis, ein Gesicht mit Hut?","Zeigt euch gegenseitig, was ihr entdeckt habt. Sehen die anderen es auch?","Beobachtet, wie sich eine Wolke langsam verwandelt. Vielleicht wird aus dem Hasen ein Schiff.","Erfindet zu euren Wolkenbildern eine Geschichte, die mit den Wolken weiterzieht.","Größere Kinder lernen die Wolkenarten: Haufenwolken sehen aus wie Watte, Federwolken wie dünne Federn."],"safetyNote":"Schaut nie direkt in die Sonne."},"en":{"title":"Cloud Pictures","summary":"Lie on a blanket, look up at the sky and find dragons, sheep and faces in the clouds.","steps":["Spread a blanket in the garden, the park or a meadow and lie on your backs.","Look at the clouds: what do you see? A crocodile, an ice cream, a face with a hat?","Show each other what you’ve found. Can the others see it too?","Watch how a cloud slowly changes. Maybe the rabbit turns into a ship.","Make up a story about your cloud pictures that drifts along with the clouds.","Older kids learn the cloud types: puffy cumulus clouds look like cotton, thin cirrus clouds like feathers."],"safetyNote":"Never look directly at the sun."}}'::jsonb, 3, 14, 15, 30, 'outdoor', true, false, null, null, 'low', 0, array['blanket']::text[], true, 'ai', null, '2026-10-10T12:00:00.000Z'::timestamptz),
  ('nature-mandala', 'approved', 'nature', array['natureAnimals', 'craft']::text[], '{"de":{"title":"Natur-Mandala legen","summary":"Aus Blättern, Steinen, Zapfen und Stöckchen legt ihr ein rundes Kunstwerk auf den Waldboden.","steps":["Geht in den Wald, in den Park oder in den Garten und sammelt im Korb, was am Boden liegt: Blätter, Zapfen, Steine, Stöckchen, Rinde.","Pflückt nichts, was noch wächst, und lasst Pilze und unbekannte Beeren liegen.","Sucht einen flachen Platz und legt in die Mitte etwas Besonderes, zum Beispiel einen schönen Stein.","Legt rundherum Kreis für Kreis: einen Ring aus Blättern, einen aus Stöckchen, einen aus Zapfen.","Kleine Kinder legen ihre Fundstücke einfach dazu, Größere achten auf Muster und Farben.","Lasst das Mandala liegen, wenn ihr geht. Vielleicht entdeckt es jemand anderes."],"safetyNote":"Nehmt nichts in den Mund und wascht danach die Hände. Fasst Pilze und Beeren nicht an, wenn ihr sie nicht sicher kennt."},"en":{"title":"Nature Mandala","summary":"Lay out a round work of art on the forest floor with leaves, stones, pine cones and sticks.","steps":["Go to the woods, the park or the garden and collect what’s lying on the ground in the basket: leaves, pine cones, stones, sticks, bark.","Don’t pick anything that’s still growing, and leave mushrooms and unknown berries alone.","Find a flat spot and put something special in the middle, like a pretty stone.","Lay circle after circle around it: a ring of leaves, a ring of sticks, a ring of pine cones.","Little ones simply add their finds, older kids pay attention to patterns and colors.","Leave the mandala where it is when you go. Maybe someone else will discover it."],"safetyNote":"Don’t put anything in your mouth, and wash your hands afterwards. Don’t touch mushrooms or berries unless you know them for sure."}}'::jsonb, 3, 14, 30, 60, 'outdoor', false, true, null, null, 'low', 0, array['basket']::text[], true, 'ai', null, '2026-10-10T12:00:00.000Z'::timestamptz),
  ('stick-race', 'approved', 'nature', array['water', 'natureAnimals', 'games']::text[], '{"de":{"title":"Stöckchen-Rennen an der Brücke","summary":"Jeder wirft auf der einen Seite der Brücke ein Stöckchen ins Wasser. Wessen Stöckchen kommt auf der anderen Seite zuerst heraus?","steps":["Sucht eine kleine Brücke über einen Bach mit einem stabilen Geländer.","Jeder sucht sich ein Stöckchen, das er wiedererkennt: dick, krumm oder mit einem Blatt dran.","Stellt euch auf die Seite der Brücke, von der das Wasser kommt. Auf „Los“ lassen alle ihr Stöckchen gleichzeitig fallen.","Lauft auf die andere Seite und schaut: Wessen Stöckchen taucht zuerst auf?","Probiert aus, ob dicke oder dünne, lange oder kurze Stöckchen schneller sind.","Schaut nebenbei, ob ihr Fische, Wasserläufer oder Enten entdeckt."],"safetyNote":"Erwachsene bleiben die ganze Zeit dabei, und Kinder bleiben hinter dem Geländer. Niemand klettert ans Ufer, um ein Stöckchen zu holen: Bäche können tief und schnell sein."},"en":{"title":"Stick Race at the Bridge","summary":"Everyone drops a stick into the water on one side of the bridge. Whose stick comes out first on the other side?","steps":["Find a small bridge over a stream with a sturdy railing.","Everyone looks for a stick they’ll recognize: thick, crooked or with a leaf on it.","Stand on the side of the bridge where the water comes from. On “go”, everyone drops their stick at the same time.","Run to the other side and watch: whose stick shows up first?","Test whether thick or thin, long or short sticks are faster.","Look out for fish, water striders or ducks while you’re there."],"safetyNote":"An adult stays the whole time, and children stay behind the railing. Nobody climbs down to the bank to fetch a stick: streams can be deep and fast."}}'::jsonb, 3, 12, 20, 40, 'outdoor', false, false, null, null, 'low', 0, array['stick', 'stream']::text[], true, 'ai', null, '2026-10-10T12:00:00.000Z'::timestamptz),
  ('library-trip', 'approved', 'outing', array['stories', 'outings']::text[], '{"de":{"title":"Ausflug in die Bücherei","summary":"In der Stadtbücherei stöbert ihr in Bilderbüchern, Comics und Sachbüchern und lest gleich vor Ort.","steps":["Schaut kurz nach, wann die Bücherei in eurer Nähe heute geöffnet hat.","Nehmt einen Rucksack für die Bücher mit.","Sucht euch in der Kinderecke einen gemütlichen Platz. Jeder darf sich drei Bücher aussuchen.","Lest gemeinsam oder blättert: Kleinkinder schauen Bilder an, Größere lesen selbst.","Fragt am Tresen nach einem Tipp. Dort kennt man die besten Bücher.","Zum Ausleihen braucht ihr einen Ausweis, für Kinder ist er oft kostenlos. Lesen vor Ort geht auch ohne."]},"en":{"title":"Trip to the Library","summary":"At the public library, browse picture books, comics and nonfiction and read right there.","steps":["Quickly check when your local library is open today.","Bring a backpack for the books.","Find a cozy spot in the children’s corner. Everyone gets to pick three books.","Read aloud together or browse: toddlers look at pictures, older kids read on their own.","Ask at the desk for a tip. The staff know the best books.","To borrow books you need a library card, which is often free for children. Reading on site works without one."]}}'::jsonb, 1, 12, 45, 90, 'indoor', false, false, array['morning', 'afternoon']::text[], null, 'low', 0, array['backpack']::text[], true, 'ai', null, '2026-10-10T12:00:00.000Z'::timestamptz),
  ('playground-tour', 'approved', 'outing', array['movement', 'outings']::text[], '{"de":{"title":"Spielplatz-Tour","summary":"Statt immer zum selben Spielplatz geht ihr heute auf Entdeckungstour und testet zwei oder drei, die ihr noch nicht kennt.","steps":["Sucht auf einem Stadtplan oder in einer Karten-App zwei oder drei Spielplätze in eurer Nähe, die ihr noch nicht kennt.","Packt Trinkflaschen in den Rucksack und plant den Weg: zu Fuß, mit Laufrad oder Roller.","Testet jeden Spielplatz: Wie ist die Rutsche, wie hoch geht die Schaukel, gibt es Sand oder Wasser?","Vergebt nach jedem Spielplatz Punkte von 1 bis 5. Die Kinder sind die Jury.","Am Ende kürt ihr euren neuen Lieblingsspielplatz."],"safetyNote":"Nehmt auf dem Spielplatz den Fahrradhelm ab, er kann sich an Geräten verhaken. Kleine Kinder spielen in Sichtweite von Erwachsenen."},"en":{"title":"Playground Tour","summary":"Instead of the same old playground, go exploring today and test two or three you don’t know yet.","steps":["Look for two or three playgrounds nearby that you don’t know yet, on a city map or a map app.","Pack water bottles in the backpack and plan the route: on foot, on a balance bike or a scooter.","Test every playground: how’s the slide, how high does the swing go, is there sand or water?","Give each playground points from 1 to 5. The children are the jury.","At the end, crown your new favorite playground."],"safetyNote":"Take bike helmets off at the playground, they can get caught on equipment. Little children play within sight of an adult."}}'::jsonb, 2, 10, 60, 120, 'outdoor', true, true, null, null, 'medium', 0, array['drinkBottle', 'backpack']::text[], true, 'ai', null, '2026-10-10T12:00:00.000Z'::timestamptz),
  ('supermarket-rally', 'approved', 'outing', array['games', 'cooking', 'outings', 'crowds']::text[], '{"de":{"title":"Einkaufs-Rallye","summary":"Der Einkauf wird zum Spiel: Die Kinder suchen die Sachen vom Einkaufszettel und lösen kleine Aufgaben.","steps":["Schreibt oder malt gemeinsam einen Einkaufszettel. Für Kinder, die noch nicht lesen, malt ihr die Sachen auf.","Im Laden bekommt jedes Kind ein paar Dinge von der Liste, die es suchen darf.","Gebt kleine Aufgaben dazu: Findet etwas Gelbes, das man essen kann. Welche Nudeln sind am günstigsten?","Größere Kinder vergleichen Preise und rechnen aus, was der Einkauf ungefähr kostet.","An der Kasse dürfen die Kinder alles aufs Band legen und einpacken.","Geht zu einer ruhigen Zeit einkaufen, dann ist es für alle entspannter."],"safetyNote":"Kleine Kinder bleiben in Sichtweite. Vereinbart vorher einen Treffpunkt, falls ihr euch verliert, zum Beispiel die Kasse."},"en":{"title":"Supermarket Rally","summary":"Grocery shopping turns into a game: the kids find the items on the list and solve little challenges.","steps":["Write or draw a shopping list together. For children who can’t read yet, draw the items.","In the store, each child gets a few things from the list to find.","Add little challenges: find something yellow you can eat. Which pasta is the cheapest?","Older kids compare prices and work out roughly what the shopping costs.","At the checkout, the children put everything on the belt and pack it up.","Go at a quiet time, it’s more relaxed for everyone."],"safetyNote":"Small children stay within sight. Agree on a meeting point in advance in case you lose each other, for example the checkout."}}'::jsonb, 4, 10, 30, 45, 'indoor', false, false, null, null, 'medium', 0, array['paper', 'pencils', 'basket']::text[], true, 'ai', null, '2026-10-10T12:00:00.000Z'::timestamptz),
  ('ride-into-the-unknown', 'approved', 'outing', array['technology', 'outings', 'longTrips']::text[], '{"de":{"title":"Mit Bus oder Bahn ins Blaue","summary":"Ihr steigt in einen Bus oder eine Bahn und fahrt bis zu einer Haltestelle, an der ihr noch nie ausgestiegen seid.","steps":["Packt Trinkflaschen in den Rucksack und kauft eine Tageskarte oder Fahrkarten für hin und zurück.","Geht zur nächsten Haltestelle und nehmt den Bus oder die Bahn, die als Erstes kommt.","Die Kinder bestimmen, wo ihr aussteigt, zum Beispiel wegen eines lustigen Namens oder nach fünf Stationen.","Erkundet die Gegend rund um die Haltestelle: Gibt es einen Spielplatz, einen Bäcker, einen Park?","Schaut rechtzeitig nach, wann ein Bus oder eine Bahn zurückfährt.","Erzählt euch auf der Rückfahrt, was ihr Neues entdeckt habt."],"safetyNote":"Vereinbart, dass alle zusammen ein- und aussteigen, und haltet kleine Kinder an der Hand. Merkt euch, wie ihr zurückkommt."},"en":{"title":"Bus or Train Ride into the Unknown","summary":"Hop on a bus or train and ride to a stop where you’ve never gotten off before.","steps":["Pack water bottles in the backpack and get a day ticket or tickets for there and back.","Go to the nearest stop and take whichever bus or train comes first.","The children decide where to get off, for example because of a funny name or after five stops.","Explore the area around the stop: is there a playground, a bakery, a park?","Check in good time when a bus or train goes back.","On the way home, tell each other what new things you discovered."],"safetyNote":"Agree that everyone gets on and off together, and hold little children’s hands. Make sure you know how to get back."}}'::jsonb, 3, 14, 120, 240, 'both', false, false, array['morning', 'afternoon']::text[], null, 'medium', 1, array['backpack', 'drinkBottle']::text[], true, 'ai', null, '2026-10-10T12:00:00.000Z'::timestamptz),
  ('summit-hike', 'approved', 'outing', array['outings', 'movement', 'natureAnimals']::text[], '{"de":{"title":"Gipfelstürmer: Auf den höchsten Punkt in der Nähe","summary":"Ihr sucht den höchsten Hügel, Turm oder Aussichtspunkt in eurer Umgebung und erobert ihn zu Fuß.","steps":["Schaut auf einer Karte nach: Wo ist der höchste Punkt in eurer Nähe? Ein Hügel, ein Aussichtsturm, ein Berg?","Packt Trinkflaschen und eine warme Jacke in den Rucksack, oben ist es oft windiger.","Lasst die Kinder das Tempo bestimmen und macht kleine Pausen an Bänken oder schönen Stellen.","Oben angekommen: Was könnt ihr sehen? Euer Zuhause, die Schule, einen Kirchturm?","Malt zu Hause eine Karte von allem, was ihr von oben gesehen habt.","Größere Kinder lesen die Karte und führen die Gruppe."],"safetyNote":"Plant den Weg so, dass auch die Jüngsten ihn schaffen. Bleibt auf den Wegen und kehrt bei Gewitter sofort um."},"en":{"title":"Summit Stormers: Climb the Highest Point Nearby","summary":"Find the highest hill, tower or viewpoint in your area and conquer it on foot.","steps":["Look at a map: where is the highest point near you? A hill, a lookout tower, a mountain?","Pack water bottles and a warm jacket in the backpack, it’s often windier at the top.","Let the children set the pace and take short breaks at benches or nice spots.","At the top: what can you see? Your home, the school, a church tower?","Back home, draw a map of everything you saw from the top.","Older kids read the map and lead the group."],"safetyNote":"Plan the route so even the youngest can manage it. Stay on the paths and turn back right away if a thunderstorm comes."}}'::jsonb, 5, 16, 90, 180, 'outdoor', true, true, array['morning', 'afternoon']::text[], null, 'high', 0, array['backpack', 'drinkBottle', 'warmClothes']::text[], true, 'ai', null, '2026-10-10T12:00:00.000Z'::timestamptz),
  ('cornstarch-goo', 'approved', 'experiment', array['experiments', 'gettingDirty']::text[], '{"de":{"title":"Zauberschleim aus Speisestärke","summary":"Mal fest, mal flüssig: Speisestärke und Wasser ergeben eine Masse, die sich wie Zauberei anfühlt.","steps":["Zieht alte T-Shirts an und stellt ein Tablett unter die Schüssel.","Gebt etwa 8 Esslöffel Speisestärke in die Schüssel und rührt nach und nach 4 bis 5 Esslöffel Wasser unter.","Die Masse ist richtig, wenn sie beim schnellen Rühren zäh wird, aber vom Finger tropft, wenn ihr langsam seid.","Schlagt schnell mit der Faust darauf: Die Oberfläche wird hart. Taucht die Hand langsam ein: Sie versinkt wie in Honig.","Nehmt eine Handvoll und knetet sie zu einer Kugel. Hört ihr auf zu kneten, zerfließt sie in der Hand.","Lasst die Reste eintrocknen und werft sie in den Müll, nicht in den Abfluss, sonst verstopft er."],"safetyNote":"Nicht zum Essen. Bleibt bei den Kleinen, damit nichts in den Mund kommt."},"en":{"title":"Magic Goo from Cornstarch","summary":"Solid one moment, liquid the next: cornstarch and water make a goo that feels like magic.","steps":["Put on old T-shirts and set a tray under the bowl.","Put about 8 tablespoons of cornstarch in the bowl and gradually stir in 4 to 5 tablespoons of water.","The goo is right when it gets stiff as you stir fast but drips off your finger when you move slowly.","Hit it fast with your fist: the surface turns hard. Dip your hand in slowly: it sinks like into honey.","Take a handful and knead it into a ball. Stop kneading and it melts away in your hand.","Let the leftovers dry and put them in the trash, not down the drain, or it will clog."],"safetyNote":"Not for eating. Stay with the little ones so nothing ends up in a mouth."}}'::jsonb, 3, 12, 20, 30, 'indoor', false, false, null, null, 'medium', 0, array['cornstarch', 'tapWater', 'bowl', 'tray', 'oldShirt']::text[], true, 'ai', null, '2026-10-10T12:00:00.000Z'::timestamptz),
  ('foil-boats', 'approved', 'experiment', array['experiments', 'water', 'building']::text[], '{"de":{"title":"Welches Boot trägt am meisten?","summary":"Ihr baut Boote aus Alufolie und ladet so lange Münzen ein, bis sie sinken.","steps":["Füllt eine große Schüssel oder das Waschbecken halb mit Wasser und legt ein Handtuch darunter.","Jeder bekommt ein gleich großes Stück Alufolie, etwa so groß wie ein halbes Blatt Papier.","Formt daraus ein Boot: flach und breit, hoch und schmal oder ganz anders.","Setzt die Boote aufs Wasser und legt nacheinander Münzen hinein, immer eine nach der anderen.","Zählt mit: Welches Boot trägt die meisten Münzen, bevor es sinkt?","Überlegt, welche Form am besten war, und baut in einer zweiten Runde ein noch besseres Boot."],"safetyNote":"Erwachsene bleiben die ganze Zeit dabei, solange Wasser in der Schüssel ist. Münzen sind Kleinteile: Sammelt sie danach ein, besonders wenn kleine Geschwister da sind."},"en":{"title":"Which Boat Carries the Most?","summary":"Build boats out of aluminum foil and load them with coins until they sink.","steps":["Fill a large bowl or the sink halfway with water and put a towel underneath.","Everyone gets the same size piece of aluminum foil, about as big as half a sheet of paper.","Shape it into a boat: flat and wide, tall and narrow, or something else entirely.","Put the boats on the water and add coins one at a time.","Count along: which boat carries the most coins before it sinks?","Think about which shape worked best, and build an even better boat in a second round."],"safetyNote":"An adult stays the whole time while there’s water in the bowl. Coins are small parts: collect them afterwards, especially when little siblings are around."}}'::jsonb, 4, 12, 20, 30, 'indoor', false, false, null, null, 'low', 0, array['aluminumFoil', 'coins', 'water', 'bowl', 'towel']::text[], true, 'ai', null, '2026-10-10T12:00:00.000Z'::timestamptz),
  ('secret-lemon-ink', 'approved', 'experiment', array['experiments', 'roleplay']::text[], '{"de":{"title":"Geheimschrift mit Zitronensaft","summary":"Ihr schreibt mit Zitronensaft eine unsichtbare Botschaft. Erst mit Wärme wird sie lesbar, wie bei echten Geheimagenten.","steps":["Ein Erwachsener schneidet eine Zitrone auf. Presst etwas Saft in einen Becher.","Taucht ein Wattestäbchen in den Saft und schreibt oder malt eine Botschaft auf weißes Papier.","Lasst das Papier ganz trocknen. Jetzt ist die Schrift unsichtbar.","Tauscht die Briefe aus. Kann jemand die Geheimbotschaft lesen?","Zum Entschlüsseln bügelt ein Erwachsener das Papier ohne Dampf auf mittlerer Stufe. Langsam wird die Schrift braun und lesbar.","Größere Kinder denken sich zusätzlich einen Code aus, zum Beispiel jeden Buchstaben um eins im Alphabet verschoben."],"safetyNote":"Messer und Bügeleisen bedienen nur Erwachsene. Das Bügeleisen bleibt auch nach dem Ausschalten heiß: Stellt es außer Reichweite ab."},"en":{"title":"Secret Lemon Ink","summary":"Write an invisible message in lemon juice. Only heat makes it readable, just like real secret agents.","steps":["An adult cuts a lemon open. Squeeze some juice into a cup.","Dip a cotton swab into the juice and write or draw a message on white paper.","Let the paper dry completely. Now the writing is invisible.","Swap letters. Can anyone read the secret message?","To decode it, an adult irons the paper on a medium setting without steam. Slowly the writing turns brown and readable.","Older kids also invent a code, for example shifting every letter one place along the alphabet."],"safetyNote":"Only adults use the knife and the iron. The iron stays hot even after it’s switched off: put it out of reach."}}'::jsonb, 6, 12, 20, 30, 'indoor', false, false, null, null, 'low', 0, array['lemon', 'knife', 'plasticCup', 'cottonSwabs', 'paper', 'iron']::text[], true, 'ai', null, '2026-10-10T12:00:00.000Z'::timestamptz),
  ('red-cabbage-color-magic', 'approved', 'experiment', array['experiments', 'cooking']::text[], '{"de":{"title":"Rotkohl-Zauberwasser","summary":"Rotkohlwasser wechselt die Farbe: Mit Essig wird es pink, mit Natron grün. So testet ihr, was sauer ist.","steps":["Ein Erwachsener schneidet ein paar Blätter Rotkohl klein und gibt sie in eine Schüssel.","Gießt heißes Wasser aus dem Wasserkocher darüber und lasst alles 10 Minuten ziehen, bis das Wasser tief lila ist.","Gießt das lila Wasser vorsichtig ohne die Blätter in ein Glas und lasst es abkühlen.","Verteilt das Rotkohlwasser auf mehrere Becher.","Ratet vorher und schreibt es auf: Wird es rosa (sauer) oder grün-blau (das Gegenteil, basisch)?","Gebt in jeden Becher etwas anderes: Essig, Zitronensaft, Natron, Spülmittel, Leitungswasser. Was passiert mit der Farbe?"],"safetyNote":"Messer und heißes Wasser nur mit Erwachsenen. Die Mischungen nicht trinken und nicht in die Augen bringen."},"en":{"title":"Red Cabbage Color Magic","summary":"Red cabbage water changes color: vinegar turns it pink, baking soda turns it green. That’s how you test what’s acidic.","steps":["An adult chops a few red cabbage leaves and puts them in a bowl.","Pour hot water from the kettle over them and let everything steep for 10 minutes until the water is deep purple.","Carefully pour the purple water into a jar without the leaves and let it cool.","Divide the cabbage water among several cups.","Guess first and write it down: will it turn pink (acidic) or green-blue (the opposite, basic)?","Add something different to each cup: vinegar, lemon juice, baking soda, dish soap, tap water. What happens to the color?"],"safetyNote":"Knife and hot water only with adults. Don’t drink the mixtures, and keep them out of your eyes."}}'::jsonb, 7, 16, 30, 45, 'indoor', false, false, null, null, 'medium', 1, array['redCabbage', 'knife', 'kettle', 'bowl', 'jar', 'plasticCup', 'vinegar', 'lemon', 'bakingSoda', 'dishSoap', 'tapWater', 'paper', 'pencils']::text[], true, 'ai', null, '2026-10-10T12:00:00.000Z'::timestamptz),
  ('chain-reaction', 'approved', 'experiment', array['building', 'technology', 'experiments']::text[], '{"de":{"title":"Kettenreaktion bauen","summary":"Ein Ball stößt Bücher um, die Bücher eine Murmel, die Murmel einen Becherturm: Ihr baut eine Maschine, die von allein abläuft.","steps":["Sammelt Dinge, die rollen, kippen oder fallen: Bücher, Spielkarten, Papprollen, Murmeln, einen Ball, Becher.","Legt das Ziel fest: Am Ende soll zum Beispiel ein Becherturm einstürzen.","Baut Schritt für Schritt: Stellt Bücher wie Dominosteine auf, legt eine Rampe aus Papprollen, lasst eine Murmel in einen Becher rollen.","Testet jeden Abschnitt einzeln, bevor ihr ihn mit dem nächsten verbindet.","Geht etwas schief? Das gehört dazu. Verschiebt, klebt fest und probiert es wieder.","Wenn alles steht, schauen alle zu, und die jüngste Person gibt den ersten Anstoß."],"safetyNote":"Murmeln sind Kleinteile: Sammelt sie danach ein, wenn kleine Geschwister in der Nähe sind."},"en":{"title":"Build a Chain Reaction","summary":"A ball knocks over books, the books a marble, the marble a tower of cups: build a machine that runs all by itself.","steps":["Collect things that roll, tip or fall: books, playing cards, cardboard tubes, marbles, a ball, cups.","Set the goal: at the end, a tower of cups should collapse, for example.","Build step by step: stand books up like dominoes, make a ramp from cardboard tubes, let a marble roll into a cup.","Test each section on its own before connecting it to the next.","Something goes wrong? That’s part of it. Move things, tape them down and try again.","When everything is set, everyone watches, and the youngest person gives the first push."],"safetyNote":"Marbles are small parts: collect them afterwards when little siblings are nearby."}}'::jsonb, 8, 16, 60, 120, 'indoor', false, false, null, null, 'medium', 0, array['book', 'playingCards', 'cardboardTubes', 'marbles', 'ball', 'plasticCup', 'tape']::text[], true, 'ai', null, '2026-10-10T12:00:00.000Z'::timestamptz),
  ('teddy-vet', 'approved', 'game', array['roleplay', 'natureAnimals']::text[], '{"de":{"title":"Kuscheltier-Tierarzt","summary":"Die Kuscheltiere sind krank und brauchen eine Untersuchung. Die Kinder sind die Ärzte, die Eltern dürfen im Wartezimmer sitzen.","steps":["Richtet eine Tierarztpraxis ein: Ein Handtuch ist der Behandlungstisch, ein Tuch der Verband.","Die Eltern bringen ein Kuscheltier und erzählen, was ihm fehlt: Bauchweh, ein verstauchtes Bein, Schnupfen.","Die Kinder untersuchen: Herz abhören, ins Ohr schauen, mit einem Löffel als Thermometer Fieber messen.","Verbindet das kranke Bein mit dem Tuch oder legt das Tier zum Ausruhen ins Bett.","Größere Kinder schreiben oder malen ein Rezept: zweimal am Tag kuscheln.","Dann ist der nächste Patient dran. Wer mag, tauscht die Rollen."]},"en":{"title":"Teddy Vet","summary":"The stuffed animals are sick and need a check-up. The children are the doctors, the parents get to sit in the waiting room.","steps":["Set up a vet clinic: a towel is the exam table, a cloth is the bandage.","The parents bring a stuffed animal and explain what’s wrong: tummy ache, a sprained leg, a cold.","The children examine it: listen to its heart, look in its ears, take its temperature with a spoon as a thermometer.","Bandage the sore leg with the cloth or put the animal to bed to rest.","Older kids write or draw a prescription: cuddle twice a day.","Then it’s the next patient’s turn. Switch roles if you like."]}}'::jsonb, 2, 7, 20, 40, 'indoor', false, false, null, null, 'low', 0, array['stuffedAnimals', 'towel', 'scarf', 'spoon', 'paper', 'pencils']::text[], true, 'ai', null, '2026-10-10T12:00:00.000Z'::timestamptz),
  ('play-restaurant', 'approved', 'game', array['roleplay', 'cooking']::text[], '{"de":{"title":"Restaurant spielen","summary":"Die Kinder eröffnen ein Restaurant mit Speisekarte und Bedienung. Die Erwachsenen sind die Gäste und dürfen sitzen bleiben.","steps":["Die Kinder denken sich einen Namen für ihr Restaurant aus und malen eine Speisekarte mit erfundenen Gerichten.","Deckt einen Tisch mit Tellern und Bechern. Ein Handtuch über dem Arm macht aus jedem Kind einen Kellner.","Die Gäste kommen herein, bekommen die Karte und bestellen.","In der Küche malen die Köche das Essen auf Papier und servieren es auf dem Tablett.","Die Gäste loben oder beschweren sich, natürlich höflich. Bezahlt wird mit erfundenem Geld.","Kleinere Kinder sind Kellner, Größere schreiben die Bestellungen auf und rechnen die Rechnung aus."]},"en":{"title":"Play Restaurant","summary":"The children open a restaurant with a menu and table service. The adults are the guests and get to stay seated.","steps":["The children come up with a name for their restaurant and draw a menu of made-up dishes.","Set a table with plates and cups. A towel over the arm turns any child into a waiter.","The guests come in, get the menu and order.","In the kitchen, the chefs draw the food on paper and serve it on the tray.","The guests praise the food or complain, politely of course. The bill is paid with pretend money.","Younger children are waiters, older ones write down the orders and add up the bill."]}}'::jsonb, 3, 10, 30, 60, 'indoor', false, false, null, null, 'low', 0, array['paper', 'pencils', 'plate', 'plasticCup', 'tray', 'towel']::text[], true, 'ai', null, '2026-10-10T12:00:00.000Z'::timestamptz),
  ('dress-up-fashion-show', 'approved', 'game', array['roleplay', 'music']::text[], '{"de":{"title":"Verkleiden und Modenschau","summary":"Aus alten Kleidern, Tüchern und Hüten entstehen Kostüme, die auf einem Laufsteg im Flur vorgeführt werden.","steps":["Sammelt alte Kleidung, Tücher und Hüte auf einem großen Haufen. Die Sachen der Eltern sind besonders beliebt.","Jeder stellt sich ein Kostüm zusammen: Königin, Pirat, Astronautin, Wetterfee oder etwas ganz Eigenes.","Legt im Flur ein Handtuch als Laufsteg aus und macht passende Musik an.","Nacheinander läuft jeder über den Laufsteg, dreht sich am Ende und posiert.","Die Zuschauer klatschen und raten, wer oder was das sein soll.","Größere Kinder kündigen ihre Figur mit einem kurzen Auftritt an, Kleine laufen einfach mit."],"safetyNote":"Bei kleinen Kindern keine Schnüre oder Schals locker um den Hals, und keine langen Kleider auf der Treppe."},"en":{"title":"Dress-Up Fashion Show","summary":"Old clothes, scarves and hats turn into costumes that get shown off on a runway in the hallway.","steps":["Gather old clothes, scarves and hats into one big pile. Grown-ups’ clothes are especially popular.","Everyone puts together a costume: a queen, a pirate, an astronaut, a weather presenter or something completely new.","Lay a towel down in the hallway as a runway and put on some fitting music.","One after another, everyone walks the runway, turns at the end and strikes a pose.","The audience claps and guesses who or what it’s supposed to be.","Older kids announce their character with a short performance, little ones just walk along."],"safetyNote":"No loose cords or scarves around little children’s necks, and no long dresses on the stairs."}}'::jsonb, 3, 10, 30, 45, 'indoor', false, false, null, null, 'low', 0, array['dressUpClothes', 'scarf', 'towel', 'musicPlayer']::text[], true, 'ai', null, '2026-10-10T12:00:00.000Z'::timestamptz),
  ('chestnut-animals', 'approved', 'craft', array['craft', 'natureAnimals']::text[], '{"de":{"title":"Kastanientiere basteln","summary":"Aus Kastanien und Zahnstochern entstehen Igel, Pferde, Spinnen und ganze Familien.","steps":["Sammelt auf einem Herbstspaziergang Kastanien, am besten frisch heruntergefallene. Die sind noch weich genug.","Ein Erwachsener sticht mit einem Holzspieß kleine Löcher in die Kastanien, dort wo Beine, Hals und Kopf hinkommen.","Steckt Zahnstocher in die Löcher und verbindet so mehrere Kastanien miteinander.","Probiert verschiedene Tiere: Eine Kastanie mit vier Zahnstocher-Beinen wird ein Pferd, eine mit vielen Zahnstochern ein Igel.","Malt mit Filzstiften Augen und Muster auf.","Baut eine ganze Kastanienfamilie und gebt allen Namen."],"safetyNote":"Löcher stechen nur Erwachsene. Zahnstocher sind spitz. Kastanien sind nicht essbar, und kleine Kinder können sich daran verschlucken: Nichts in den Mund nehmen und kleine Geschwister fernhalten."},"en":{"title":"Chestnut Animals","summary":"Chestnuts and toothpicks turn into hedgehogs, horses, spiders and whole families.","steps":["Collect chestnuts on an autumn walk, ideally freshly fallen ones. They’re still soft enough.","An adult pokes small holes into the chestnuts with a wooden skewer where the legs, neck and head should go.","Push toothpicks into the holes to connect several chestnuts.","Try different animals: a chestnut with four toothpick legs becomes a horse, one with lots of toothpicks a hedgehog.","Draw eyes and patterns on them with markers.","Build a whole chestnut family and give everyone a name."],"safetyNote":"Only adults poke the holes. Toothpicks are pointy. Horse chestnuts are not edible, and small children can choke on them: don’t put anything in your mouth, and keep little siblings away."}}'::jsonb, 4, 10, 30, 60, 'indoor', false, false, null, array[9, 10, 11]::smallint[], 'medium', 0, array['chestnuts', 'skewer', 'toothpicks', 'markers']::text[], true, 'ai', null, '2026-10-10T12:00:00.000Z'::timestamptz)
on conflict (id) do update set
  status = excluded.status,
  category = excluded.category,
  topics = excluded.topics,
  translations = excluded.translations,
  age_min = excluded.age_min,
  age_max = excluded.age_max,
  duration_min = excluded.duration_min,
  duration_max = excluded.duration_max,
  setting = excluded.setting,
  needs_dry = excluded.needs_dry,
  better_in_sun = excluded.better_in_sun,
  day_parts = excluded.day_parts,
  months = excluded.months,
  energy = excluded.energy,
  cost = excluded.cost,
  materials = excluded.materials,
  sibling_friendly = excluded.sibling_friendly,
  source = excluded.source,
  image = excluded.image,
  created_at = excluded.created_at
where (activities.status, activities.category, activities.topics, activities.translations, activities.age_min, activities.age_max, activities.duration_min, activities.duration_max, activities.setting, activities.needs_dry, activities.better_in_sun, activities.day_parts, activities.months, activities.energy, activities.cost, activities.materials, activities.sibling_friendly, activities.source, activities.image, activities.created_at)
  is distinct from (excluded.status, excluded.category, excluded.topics, excluded.translations, excluded.age_min, excluded.age_max, excluded.duration_min, excluded.duration_max, excluded.setting, excluded.needs_dry, excluded.better_in_sun, excluded.day_parts, excluded.months, excluded.energy, excluded.cost, excluded.materials, excluded.sibling_friendly, excluded.source, excluded.image, excluded.created_at);

-- Zur Kontrolle: Nach dem letzten Teil steht hier die Gesamtzahl.
select count(*) as aktivitaeten_insgesamt from public.activities;
